<?php
namespace Tests\Feature\Advertising;
use App\Models\{AdPlacement,Advertiser,AdvertisingCampaign,Permission,User}; use Illuminate\Foundation\Testing\RefreshDatabase; use Tests\TestCase;
class AdvertisingFoundationTest extends TestCase { use RefreshDatabase; public function test_advertising_foundation_models_work_and_routes_are_protected():void { $advertiser=Advertiser::factory()->create(); $placement=AdPlacement::factory()->create(); $campaign=AdvertisingCampaign::factory()->create(['advertiser_id'=>$advertiser->id]); $campaign->placements()->attach($placement); $this->assertEquals($advertiser->id,$campaign->advertiser->id); $this->assertCount(1,$campaign->placements); $this->get('/admin/ad-campaigns')->assertRedirect('/login'); } public function test_authorized_admin_can_view_advertising_pages():void { foreach(['view_admin','manage_advertisers','manage_ad_campaigns','manage_ad_placements'] as $name){$permissions[]=Permission::query()->create(['name'=>$name,'label'=>str($name)->replace('_',' ')->title(),'description'=>$name,'group_name'=>'Advertising','is_system'=>true,'is_locked'=>true]);} $user=User::factory()->create(['email_verified_at'=>now()]);$user->permissions()->sync(collect($permissions)->pluck('id'));$this->actingAs($user)->get('/admin/advertisers')->assertOk()->assertInertia(fn($p)=>$p->component('Admin/Advertising/Advertisers/Index'));$this->actingAs($user)->get('/admin/ad-placements')->assertOk();$this->actingAs($user)->get('/admin/ad-campaigns')->assertOk(); } }
